//! Cargo-driven `d3dx10_43.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", None),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", None),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", None),
        o => panic!("d3dx10_43-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "engine:c:dxguid", "engine:c:dx10guid", "engine:uuid", "import:d3d10_1", "import:d3dcompiler_47", "import:d3dx9_36", "import:gdi32", "import:kernel32_vista", "import:ntdll_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:windowscodecs", "body", "engine:oldnames", "engine:delayimp_rust"],
        "x86_64" => &["engine:wine", "engine:c:dxguid", "engine:c:dx10guid", "engine:uuid", "import:d3d10_1", "import:d3dcompiler_47", "import:d3dx9_36", "import:gdi32", "import:kernel32_vista", "import:ntdll_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:windowscodecs", "body", "engine:oldnames", "engine:delayimp_rust"],
        "aarch64" => &["engine:wine", "engine:c:dxguid", "engine:c:dx10guid", "engine:uuid", "import:d3d10_1", "import:d3dcompiler_47", "import:d3dx9_36", "import:gdi32", "import:kernel32_vista", "import:ntdll_vista", "import:msvcrt", "import:kernel32", "import:ntdll", "import:windowscodecs", "body", "engine:oldnames", "engine:delayimp_rust"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/directx/wine/d3dx10_43",
        "dll/directx/wine/d3dx10_43",
        "@build/sdk/include/wine",
        "sdk/include/wine",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
        "vendor/libtiff/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "WINVER=0x0600",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_DLL",
        "_WIN32_WINNT=0x0600",
        "__ROS_LONG64__",
        "__USE_CRTIMP",
        "__WINESRC__",
    ];

    Linker::new(target_json)
        .c_from_compile_db("d3dx10_43_shims", &["dll/directx/wine/d3dx10_43/async.c", "dll/directx/wine/d3dx10_43/compiler.c", "dll/directx/wine/d3dx10_43/d3dx10_43_main.c", "dll/directx/wine/d3dx10_43/font.c", "dll/directx/wine/d3dx10_43/mesh.c", "dll/directx/wine/d3dx10_43/sprite.c", "dll/directx/wine/d3dx10_43/texture.c", "dll/directx/wine/d3dx10_43/guid.c"])
        .rc("dll/directx/wine/d3dx10_43/version.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/directx/wine/d3dx10_43/d3dx10_43.spec", "d3dx10_43.dll")
        .spec_stubs()
        .import_lib("dll/directx/wine/d3d10_1/d3d10_1.spec", "d3d10_1.dll", "d3d10_1")
        .import_lib("dll/directx/wine/d3dcompiler_47/d3dcompiler_47.spec", "d3dcompiler_47.dll", "d3dcompiler_47")
        .import_lib("dll/directx/wine/d3dx9_36/d3dx9_36.spec", "d3dx9_36.dll", "d3dx9_36")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/kernel32/kernel32_vista/kernel32_vista.spec", "kernel32_vista.dll", "kernel32_vista")
        .import_lib("dll/ntdll/nt_0600/ntdll_vista.spec", "ntdll_vista.dll", "ntdll_vista")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        .delay_import_lib("dll/win32/windowscodecs/windowscodecs.spec", "windowscodecs.dll", "windowscodecs")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
